/// <summary>
/// When an instance of TAMRebateDatePeriod is created, this method will set the TAMRebateTransactionType
/// So we can update the RebateTransIdMapKey to add vendorRebateTypeId only in the rebate transaction type scenario TAMRebateDatePeriod\getRebateTransIdMapKey.
/// </summary>
/// <param name = "_instance">Instance of <c>TAMRebateDatePeriod</c></param>
/// <param name = "_transactionType">Rebate transaction type</param>
/// <returns>Instance of <c>TAMRebateDatePeriod</c> set with the TAMRebateTransactionType</returns>
public static TAMRebateDatePeriod newDatePeriodByTransactionType(TAMRebateDatePeriod _instance, TAMRebateTransactionType _transactionType)
{
    TAMRebateDatePeriod instance = next newDatePeriodByTransactionType(_instance, _transactionType);

    instance.metParmRebateTransactionType(_transactionType);

    return instance;
}

/// <summary>
/// Include the new enum value for DynamicAccount so it can work with TAMRebateConsolidateVendorInvoiceByDimensionFeature
/// in class TAMRebatePostDateTransactionFinancial\processRebateDateTransaction
/// </summary>
/// <param name = "_createDocument"><c>TAMRebateCreateDocumentFinancial</c> object</param>
/// <returns>true if the dyanmics account is METPurchasedFromVendor; otherwise, false.</returns>
public static boolean checkCreateDocumentDynamicAccount(TAMRebateCreateDocumentFinancial _createDocument)
{
    boolean ret = next checkCreateDocumentDynamicAccount(_createDocument);

    ret = _createDocument.getRebatePosting().DynamicAccount == TAMRebateDynamicAccount::METPurchasedFromVendor;

    return ret;
}
